// ============================================
// NORMALIZE INPUT
// Parses Zoho Flow query params.
// LIMITS: last 3 emails, last 3 notes.
// ============================================

const query = $input.item.json.query || {};
const body = $input.item.json.body || {};
const headers = $input.item.json.headers || {};

const isFromZohoFlow = (headers['user-agent'] || '').includes('ZohoFlow');

// ---- DETECT TRIGGER TYPE ----
let triggerType = 'email_response';
if (body.type === 'end-of-call-report' || body.transcript) {
  triggerType = 'vapi_report';
} else if (isFromZohoFlow) {
  triggerType = 'crm_task';
} else if (body.waId || body.whatsappMessageId || (body.type === 'message' && body.phone)) {
  triggerType = 'whatsapp_response';
}

// ---- PARSE NOTES (ALL — no truncation) ----
let notes = [];
try { notes = JSON.parse(query.notecontent || '[]'); } catch(e) { notes = []; }

const lastNote = notes.length > 0 
  ? notes[0] 
  : { content: 'No previous notes', created_time: 'unknown' };

const notesHistory = notes.map(n => {
  const date = n.created_time ? n.created_time.split('T')[0] : 'unknown';
  const creator = n.created_by || n.owner || '';
  const creatorStr = creator ? ` by ${creator}` : '';
  return `[${date}]${creatorStr} ${n.content}`;
}).join('\n');

// ---- PARSE & LIMIT EMAILS (last 3, truncate body to 400 chars) ----
// NOTE: emailcontent moved to POST body in Zoho Flow 1 to avoid URL length limits with large email histories
let emailData = { emails: [], email_count: 0 };
try {
  let rawEmail = body.emailcontent || query.emailcontent || '{}';
  if (typeof rawEmail === 'string') {
    try { rawEmail = decodeURIComponent(rawEmail); } catch(e2) {}
  }
  if (typeof rawEmail === 'string' && rawEmail.startsWith('"')) {
    rawEmail = JSON.parse(rawEmail);
  }
  emailData = typeof rawEmail === 'string' ? JSON.parse(rawEmail) : rawEmail;
} catch(e) {
  emailData = { emails: [], email_count: 0 };
}

const allEmails = emailData.emails || [];
const recentEmails = allEmails.slice(0, 3);

const emailHistory = recentEmails.map(e => {
  const date = e.sent_time ? e.sent_time.split('T')[0] : 'unknown';
  const from = e.from_email || e.from || 'unknown';
  const subject = e.subject || '(no subject)';
  const body_text = (e.text_content || e.content || '').substring(0, 400);
  return `--- Email [${date}] from: ${from} ---\nSubject: ${subject}\n${body_text}`;
}).join('\n\n');

// ---- PARSE TIMELINE ----
let timeline = {};
try { timeline = JSON.parse(query.commtimeline || query.timeline || '{}'); } catch(e) { timeline = {}; }

// ---- LEAD ID ----
const leadId = (query.leadid || body.leadId || body.lead_id || emailData.lead_id || '').trim();

// ---- FROM EMAIL (sender's email address, for contact lookup) ----
const fromEmail = allEmails.length > 0 ? (allEmails[0].from_email || allEmails[0].from || '') : '';

// ---- PHONE (from WATI inbound) ----
const incomingPhone = body.waId || body.phone || body.from || '';

// ---- INCOMING WA MESSAGE (supports text/audio/image/document) ----
let incomingWAMessage = '';
let waMessageType = 'text';
let mediaUrl = '';
let fileName = '';
let caption = '';
let senderName = '';

if (body.waId || body.whatsappMessageId) {
  waMessageType = body.type || 'text';
  senderName = body.senderName || body.pushName || '';
  if (waMessageType === 'text') {
    incomingWAMessage = (typeof body.text === 'string') ? body.text : (body.text?.body || body.text || '');
  } else if (waMessageType === 'audio' || waMessageType === 'voice') {
    waMessageType = 'audio';
    mediaUrl = body.data || body.mediaUrl || '';
    caption = body.text || '';
  } else if (waMessageType === 'image') {
    mediaUrl = body.data || body.mediaUrl || '';
    caption = body.text || body.caption || '';
  } else if (waMessageType === 'document') {
    mediaUrl = body.data || body.mediaUrl || '';
    fileName = body.fileName || '';
    caption = body.text || body.caption || '';
  }
}

// ---- EMAIL HTML + IMAGE URLS ----
// emailhtml and emailimages moved to POST body in Zoho Flow 1 to avoid URL length limits
const emailHtml = body.emailhtml || (query.emailhtml ? decodeURIComponent(query.emailhtml) : '');
const rawImageUrls = body.emailimages || query.emailimages || '';
const imageUrls = rawImageUrls
  .split(',')
  .map(u => u.trim())
  .filter(u => u.startsWith('http'));

// ---- EMAIL METADATA (paginated list from getAllLeadEmailsMeta via Zoho Flow 1) ----
// Moved to POST body — body takes priority, query is fallback for backwards compatibility
const emailMetadata = body.email_metadata || query.email_metadata || '';

// ---- PARSE VAPI DATA (if call report) ----
const vapiData = {
  transcript: body.transcript || '',
  recording_url: body.recordingUrl || body.recording_url || '',
  call_duration: body.duration || body.call_duration || 0,
  call_status: body.status || body.endedReason || '',
  cost: body.cost || 0,
  structured_data: body.analysis || body.structured_data || null
};

return {
  json: {
    trigger_type: triggerType,
    lead_id: leadId,
    notes: {
      count: parseInt(query.notecount || '0'),
      last_note: lastNote.content || 'No notes',
      last_note_date: lastNote.created_time || 'unknown',
      full_history: notesHistory || 'No history available'
    },
    email: {
      count: parseInt(query.emailcount || '0'),
      total_communications: timeline.total_count || 0,
      full_history: emailHistory || 'No email history available'
    },
    incoming_message: body.message || incomingWAMessage || null,
    incoming_channel: body.waId ? 'whatsapp' : (body.channel || 'email'),
    incoming_phone: incomingPhone,
    from_email: fromEmail,

    wa_message_type: waMessageType,
    media_url: mediaUrl,
    file_name: fileName,
    caption: caption,
    sender_name: senderName,

    email_html: emailHtml,
    image_urls: imageUrls,
    email_metadata: emailMetadata,   // ← ADDED: passes Flow 1's getAllLeadEmailsMeta output to Merge Data

    vapi: vapiData
  }
};

// ============================================
// PARSE AI OUTPUT
// Extracts fields from AI Agent JSON response.
// Handles truncated JSON with regex fallback.
// Auto-generates cliq_message if AI skipped it.
// Cliq fallback uses lowercase labels (not ALL CAPS from CRM note).
// ============================================

const aiOutput = $input.item.json.output || $input.item.json.text || "";

let parsed;
try {
  parsed = typeof aiOutput === "string" ? JSON.parse(aiOutput) : aiOutput;
} catch (e) {
  parsed = {};
  const actionMatch = aiOutput.match(/"next_action"\s*:\s*"(\w+)"/);
  const stageMatch = aiOutput.match(/"stage_update"\s*:\s*"([^"]+)"/);
  const bodyMatch = aiOutput.match(
    /"email_body"\s*:\s*"([\s\S]*?)(?:"\s*,\s*"|$)/,
  );

  parsed.next_action = actionMatch ? actionMatch[1] : "none";
  parsed.stage_update = stageMatch ? stageMatch[1] : "Not Qualified";
  parsed.email_body = bodyMatch
    ? bodyMatch[1].replace(/\\n/g, "\n").replace(/\\"/g, '"')
    : "";
  parsed.updated_summary =
    "PARTIAL PARSE — AI response was truncated. Extracted action: " +
    parsed.next_action +
    ", stage: " +
    parsed.stage_update;
}

const cleanBody = (parsed.email_body || "")
  .replace(/\n/g, "")
  .replace(/"/g, "'");

const summary = parsed.updated_summary || "";
const leadName = $("Merge Data").first().json.lead_name || "";
const company = $("Merge Data").first().json.company || "";
const leadId = $("Merge Data").first().json.lead_id || "";

// --- Detect flags that require a Cliq notification ---
// These ALL CAPS labels are used in updated_summary (CRM note format).
const urgentFlags = [
  "STAGE NOTE:",
  "INDUSTRY NOTE:",
  "ESCALATION BLOCKED:",
  "DECISION MAKER IDENTIFIED:",
  "SIGNATURE DATA EXTRACTED:",
];
const hasUrgentFlag = urgentFlags.some((f) => summary.includes(f));
const isHumanNeeded = parsed.next_action === "human_needed";

// --- Convert ALL CAPS CRM note labels → lowercase Cliq labels ---
// The AI writes ALL CAPS in updated_summary (correct for CRM notes).
// The Cliq message must use consistent lowercase "Action taken:" style.
const flagLabelMap = {
  "STAGE NOTE:": "Stage changed:",
  "INDUSTRY NOTE:": "Industry note:",
  "ESCALATION BLOCKED:": "Escalation blocked:",
  "DECISION MAKER IDENTIFIED:": "Decision maker identified:",
  "SIGNATURE DATA EXTRACTED:": "Signature data extracted:",
  "SELF-CORRECTION NOTE:": "Self-correction:",
};
function normalizeFlags(text) {
  let result = text;
  for (const [caps, lower] of Object.entries(flagLabelMap)) {
    result = result.split(caps).join(lower);
  }
  return result;
}

// --- Map next_action to human-readable communication label ---
function actionLabel(nextAction) {
  switch (nextAction) {
    case "email":
      return "Email sent";
    case "whatsapp":
      return "WhatsApp message sent";
    case "email_and_whatsapp":
      return "Email + WhatsApp sent";
    case "call":
      return "Call triggered + follow-up email";
    case "human_needed":
      return "No outbound communication — human review needed";
    default:
      return "No outbound communication";
  }
}

// --- Auto-generate cliq_message if AI skipped it but flags exist ---
if ((hasUrgentFlag || isHumanNeeded) && !parsed.cliq_message) {
  const flagsMatch = summary.match(
    /⚠️ FLAGS:([\s\S]*?)(?:\nCRM Fields Updated:|$)/,
  );
  const flagsText = flagsMatch
    ? normalizeFlags(flagsMatch[1].trim())
    : "See CRM note";

  parsed.cliq_message =
    `🚩 Lead Flag Alert\n` +
    `Lead: ${leadName} (${company})\n` +
    `Flags:\n${flagsText}\n` +
    `Action taken: ${actionLabel(parsed.next_action || "none")}\n` +
    `Failed Updates: none\n` +
    `CRM: https://crm.zoho.com/crm/org668372427/tab/Leads/${leadId}`;
}

// --- Safety guard: block email if lead has no email address ---
// Catches cases where AI ignores the prompt rule and sets next_action='email' anyway.
const leadEmail = $("Merge Data").first().json.email || "";
const leadSecondaryEmail = $("Merge Data").first().json.secondary_email || "";
const leadPhone =
  $("Merge Data").first().json.phone ||
  $("Merge Data").first().json.mobile ||
  "";
const hasNoEmail =
  !leadEmail.trim() &&
  (!leadSecondaryEmail.trim() || leadSecondaryEmail === "Not available");

if (parsed.next_action === "email" && hasNoEmail) {
  if (leadPhone.trim()) {
    // Downgrade to WhatsApp — pick template based on country
    const spanishCountries = [
      "venezuela",
      "colombia",
      "mexico",
      "méxico",
      "peru",
      "perú",
      "chile",
      "argentina",
      "bolivia",
      "ecuador",
      "paraguay",
      "uruguay",
      "guatemala",
      "honduras",
      "el salvador",
      "nicaragua",
      "costa rica",
      "panama",
      "panamá",
      "república dominicana",
      "cuba",
      "puerto rico",
      "españa",
      "spain",
    ];
    const country = ($("Merge Data").first().json.country || "").toLowerCase();
    const waTemplate = spanishCountries.includes(country)
      ? "lead_outreach_es"
      : "lead_outreach_en";

    parsed.next_action = "whatsapp";
    parsed.wa_template = waTemplate;
    parsed.email_body = "";
    parsed.cliq_message =
      `🚩 Lead Flag Alert\n` +
      `Lead: ${leadName} (${company})\n` +
      `Flags:\n- Escalation note: No email on record — re-routed to WhatsApp (${leadPhone})\n` +
      `Action taken: WhatsApp message sent\n` +
      `Failed Updates: none\n` +
      `CRM: https://crm.zoho.com/crm/org668372427/tab/Leads/${leadId}`;
  } else {
    // No contact info at all — block
    parsed.next_action = "none";
    parsed.email_body = "";
    parsed.cliq_message =
      `🚩 Lead Flag Alert\n` +
      `Lead: ${leadName} (${company})\n` +
      `Flags:\n- Escalation blocked: No email and no phone on record — cannot contact lead. Manual lookup required.\n` +
      `Action taken: No outbound communication\n` +
      `Failed Updates: none\n` +
      `CRM: https://crm.zoho.com/crm/org668372427/tab/Leads/${leadId}`;
  }
}

return {
  json: {
    email_body: cleanBody,
    email_subject: parsed.email_subject || "",
    wa_message: parsed.wa_message || "",
    stage_update: parsed.stage_update || "Not Qualified",
    updated_summary: parsed.updated_summary || "",
    next_action: parsed.next_action || "none",
    cliq_message: parsed.cliq_message || "",
    wa_template: parsed.wa_template || "",
    lead_name: leadName,
    lead_id: leadId,
    company: company,
    country: $("Merge Data").first().json.country || "",
    last_email_id: $("Merge Data").first().json.last_email_id || "",
    mcp_email_list: $("Merge Data").first().json.mcp_email_list || [],
    email_content_prefetch:
      $("Merge Data").first().json.email_content_prefetch || "",
    wa_context_inject: parsed.wa_context_inject || "",
    wa_session_cleared: parsed.wa_session_cleared || false,
    incoming_phone: $("Normalize Input").first().json.incoming_phone || "",
  },
};

// ============================================
// MERGE DATA
// Combines: Normalize Input + MCP Client2 (getEmails) + Get WA History
// ============================================

const normalize = $("Normalize Input").first().json;

// --- Get media-processed message if Process WA Media ran ---
let incomingMessage = normalize.incoming_message;
try {
  const mediaOut = $("Process WA Media").first().json;
  if (mediaOut && mediaOut.wa_media_processed) {
    incomingMessage = mediaOut.incoming_message;
  }
} catch (e) {
  // Process WA Media didn't run (text/email/crm_task) — keep normalize value
}

// --- MCP Client2: Email list from getEmails ---
// Note: Zoho MCP returns 10 emails max per call (no pagination support).
// [TEST] emails are filtered downstream — real emails are prioritized.
let mcpEmailList = [];
try {
  const mcp1 = $("MCP Client2").first().json;
  const content1 = mcp1.content || mcp1;
  if (Array.isArray(content1)) {
    const block1 = content1.find((c) => c.type === "text");
    if (block1?.text?.Emails) mcpEmailList = [...block1.text.Emails];
  }
} catch (e) {
  mcpEmailList = [];
}

// --- Zoho Flow: Paginated email list (primary — up to 30 emails via getAllLeadEmailsMeta) ---
// WA path: email_metadata comes from Wait2 body (enricher callback)
// CRM task path: email_metadata comes from normalize (Zoho Flow query param)
let flowEmailList = [];
try {
  let rawMeta = null;
  try {
    const wait2Out = $("Wait2").first().json;
    rawMeta = wait2Out.body?.email_metadata || null;
  } catch (e) {}
  if (!rawMeta) rawMeta = normalize.email_metadata;
  if (rawMeta) {
    if (typeof rawMeta === "object") {
      // n8n auto-parsed JSON body — already an object
      flowEmailList = Array.isArray(rawMeta) ? rawMeta : [rawMeta];
    } else {
      let jsonStr = String(rawMeta).trim();
      if (!jsonStr.startsWith("[")) jsonStr = "[" + jsonStr + "]";
      const parsed = JSON.parse(jsonStr);
      if (Array.isArray(parsed) && parsed.length > 0) flowEmailList = parsed;
    }
  }
} catch (e) {
  flowEmailList = [];
}

// Prefer flow data (paginated, up to 30) over MCP (capped at 10)
const combinedEmailList =
  flowEmailList.length > 0 ? flowEmailList : mcpEmailList;

// --- WhatsApp History (TWO SOURCES) ---
// SOURCE 1: "Get WA History" = CRM-based history (for known leads)
// SOURCE 2: "Get Wati History" = WATI API (for ALL contacts, including unknown)
// Logic: Use CRM history if available. If empty, fall back to WATI API.

let waHistory = "";
let waMessageCount = 0;

// --- Source 1: CRM WA History ---
let crmWaHistory = "";
try {
  const waRaw = $("Get WA History").first().json;
  const msgs = waRaw?.messages || waRaw?.data || waRaw?.result || [];
  const crmMessages = Array.isArray(msgs) ? msgs : [];
  if (crmMessages.length > 0) {
    crmWaHistory = crmMessages
      .slice(0, 10)
      .map((m) => {
        const date = m.created
          ? new Date(m.created).toISOString().slice(0, 16)
          : "unknown";
        const direction = m.owner === true ? "Zia (Us)" : "Lead";
        const text = m.text || m.body || "";
        return `[${date}] ${direction}: ${text}`;
      })
      .join("\n");
    waMessageCount = crmMessages.length;
  }
} catch (e) {
  crmWaHistory = "";
}

// --- Source 2: WATI API History (fallback for unknown contacts) ---
let watiApiHistory = "";
try {
  const watiRaw = $("Get Wati History").first().json;
  // WATI getMessages returns: { result: "success", messages: { items: [...] } }
  const items =
    watiRaw?.messages?.items || watiRaw?.messages || watiRaw?.data || [];
  const watiMessages = Array.isArray(items) ? items : [];

  if (watiMessages.length > 0) {
    const sorted = [...watiMessages]
      .sort((a, b) => {
        const ta = a.created ? new Date(a.created).getTime() : 0;
        const tb = b.created ? new Date(b.created).getTime() : 0;
        return ta - tb;
      })
      .slice(-20);

    watiApiHistory = sorted
      .filter((m) => {
        const text = m.text || m.body || "";
        const type = m.type || "";
        if (
          !text &&
          !["image", "audio", "voice", "document", "video"].includes(type)
        )
          return false;
        if (type === "system" || type === "notification") return false;
        return true;
      })
      .map((m) => {
        const time = m.created
          ? new Date(m.created).toISOString().slice(0, 16)
          : "unknown";
        const sender = m.owner === true ? "Zia (Us)" : m.senderName || "Lead";
        const type = m.type || "text";
        let text = m.text || m.body || "";
        if (!text && type === "image") text = "[sent an image]";
        else if (!text && (type === "audio" || type === "voice"))
          text = "[sent a voice message]";
        else if (!text && type === "document") text = "[sent a document]";
        else if (!text && type === "video") text = "[sent a video]";
        return `[${time}] ${sender}: ${text}`;
      })
      .join("\n");
    waMessageCount = Math.max(waMessageCount, watiMessages.length);
  }
} catch (e) {
  watiApiHistory = "";
}

// Use CRM history if available, otherwise WATI API
waHistory = crmWaHistory || watiApiHistory;

// --- EMAIL HTML + IMAGE URLS (from extractEmailImages Deluge function via Flow 1) ---
let emailHtmlFromFlow = "";
let imageUrlsFromFlow = [];
try {
  let rawEmailHtml = normalize.email_html;
  if (typeof rawEmailHtml === "string") {
    try {
      rawEmailHtml = JSON.parse(rawEmailHtml);
    } catch (e) {}
  }
  if (Array.isArray(rawEmailHtml)) {
    emailHtmlFromFlow = rawEmailHtml
      .map((e) => {
        const date = e.sent_time ? e.sent_time.split("T")[0] : "unknown";
        const from = e.from_email || "unknown";
        const subject = e.subject || "(no subject)";
        const html = e.html_content || "";
        return `--- Email [${date}] from: ${from} ---\nSubject: ${subject}\n${html}`;
      })
      .join("\n\n");
    imageUrlsFromFlow = rawEmailHtml
      .filter((e) => {
        // Only extract images from INBOUND emails (from the lead, not from us)
        const from = (e.from_email || '').toLowerCase();
        return !from.includes('rplglobal.com') && !from.includes('care@');
      })
      .flatMap((e) => {
        const u = e.image_urls || "";
        if (Array.isArray(u)) return u;
        return typeof u === "string" && u.length > 0 ? u.split(",") : [];
      })
      .map((u) => u.trim())
      .filter((u) => u.startsWith("http"));
  } else if (typeof rawEmailHtml === "string") {
    emailHtmlFromFlow = rawEmailHtml;
  }
} catch (e) {
  emailHtmlFromFlow = "";
  imageUrlsFromFlow = [];
}

// --- Get Lead info: CRM lead fields ---
let lead = {};
try {
  const mcpOut = $("Get Lead info").first().json;
  const content = mcpOut?.content?.[0]?.text;
  if (content) {
    const parsed = typeof content === "object" ? content : JSON.parse(content);
    lead = (Array.isArray(parsed?.data) ? parsed.data[0] : parsed) || {};
  }
} catch (e) {
  lead = {};
}

// --- Extract last email message_id for reply threading ---
// FIX: skip [TEST] emails — they are sent to reviewers, not the lead
let lastMessageId = "";
let lastEmailSubject = "";
try {
  if (combinedEmailList && combinedEmailList.length > 0) {
    const lastEmail = combinedEmailList.find(
      (e) => e.message_id && !e.subject?.startsWith("[TEST]"),
    );
    if (lastEmail) {
      lastMessageId = lastEmail.message_id;
      lastEmailSubject = lastEmail.subject || "";
    }
  }
} catch (e) {
  lastMessageId = "";
  lastEmailSubject = "";
}

// --- Fallback: lead_id from staticData ---
const _phone = (normalize.incoming_phone || "").replace(/\D/g, "");
const finalLeadId =
  normalize.lead_id ||
  lead.id ||
  (_phone ? $getWorkflowStaticData("global")[`wa_lead_${_phone}`] || "" : "");

return {
  json: {
    ...normalize,
    incoming_message: incomingMessage,
    lead_id: finalLeadId,
    // Lead details from CRM
    lead_name:
      lead.Full_Name ||
      ((lead.First_Name || "") + " " + (lead.Last_Name || "")).trim() ||
      "",
    company: lead.Company || "",
    country: lead.Primary_Country || lead.Country || "",
    email: lead.Email || "",
    secondary_email: lead.Secondary_Email || "",
    phone: lead.Phone || lead.Mobile || "",
    lead_status: lead.Lead_Status || "",
    lead_owner: (lead.Owner && lead.Owner.name) || "Prateek Monga",
    industry: lead.Industry || "",
    vendor_type: lead.Vendor_Type || lead.Local_Type || "",
    vendor_portfolio: lead.Vendor_Portfolio || "",
    action_date: lead.Action_Date || "",
    last_contacted_date: lead.Last_Contacted_Date || "",
    mobile: lead.Mobile || "",
    website: lead.Website || "",
    lead_source: lead.Lead_Source || "",
    designation: lead.Designation || "",
    city: lead.City || "",
    street: lead.Street || "",
    territories:
      (lead.Territories || [])
        .map((t) => (typeof t === "object" ? t.Name : t))
        .join(", ") || "",
    created_time: lead.Created_Time || "",
    connect_count: lead.Connect_Count || 0,
    // Email list — [TEST] filtered, [Flow = up to 30 emails | MCP fallback = up to 10]
    mcp_email_list: (() => {
      const realEmails = combinedEmailList.filter(
        (e) => !e.subject?.startsWith("[TEST]"),
      );
      return realEmails.map((e) => ({
        from: e.from?.email || e.from || "",
        to: Array.isArray(e.to) ? e.to.map((t) => t.email || t) : [],
        cc: Array.isArray(e.cc)
          ? e.cc.map((c) => c.email || c).filter(Boolean)
          : [],
        subject: e.subject || "",
        time: e.time || e.sent_time || "",
        sent: !!e.sent,
        message_id: e.message_id || "",
        status: Array.isArray(e.status)
          ? e.status.map((s) => s.type || s)
          : typeof e.status === "string" && e.status.length > 0
            ? [e.status]
            : [],
        has_attachment: !!e.has_attachment,
      }));
    })(),
    test_email_count: combinedEmailList.filter((e) =>
      e.subject?.startsWith("[TEST]"),
    ).length,
    real_email_count: combinedEmailList.filter(
      (e) => !e.subject?.startsWith("[TEST]"),
    ).length,
    total_email_count: combinedEmailList.length,
    data_source: "MCP + Webhook",
    email_source:
      flowEmailList.length > 0
        ? "Zoho Flow (paginated)"
        : "MCP getEmails (10 max)",
    // Last NON-TEST email message_id + subject for reply threading
    last_email_id: lastMessageId,
    last_email_subject: lastEmailSubject,
    // WhatsApp history
    wa_history: waHistory || "No WhatsApp history available",
    wa_message_count: waMessageCount || 0,
