// ============================================
// WA SESSION GATE
// Manages session state, dedup, and Path B lock
// Paste into: WA Session Gate code node in n8n
// ============================================

const phone = ($json.incoming_phone || '').replace(/\D/g, '');
const now = Date.now();
const staticData = $getWorkflowStaticData('global');

const sessionKey = `wa_session_${phone}`;
const dedupKey = `wa_last_${phone}`;
const leadCacheKey = `wa_lead_${phone}`;
const pathBKey = `wa_pathb_${phone}`;

// --- SESSION LOCK ---
// New session if: no existing session OR last activity > 1 hour ago
const session = staticData[sessionKey] || {};
const lastActivity = session.lastActivity || 0;
const isNewSession = !session.locked || (now - lastActivity) > 3600000; // 1 hour

// Initialize or update session
if (isNewSession) {
  staticData[sessionKey] = {
    locked: true,
    startTime: now,
    lastActivity: now,
    messages: []
  };
} else {
  staticData[sessionKey].lastActivity = now;
}

// --- PATH B LOCK (prevents duplicate main-branch runs) ---
// If Path B started within 10 min, block any new execution from entering
const pathBStarted = staticData[pathBKey] || 0;
const pathBRunning = (now - pathBStarted) < 600000; // 10 min window

// FIX: shouldRunPathB also checks that the session was JUST created by THIS
// execution (isNewSession). If another execution already created the session
// (isNewSession=false), Path B won't run even if pathBRunning is somehow false.
const shouldRunPathB = isNewSession && !pathBRunning;
if (shouldRunPathB) {
  staticData[pathBKey] = now;
}

// --- DEDUP CHECK (gates BOTH quick reply AND main path) ---
// FIX: Increased from 5s to 30s. This catches:
//   - WATI duplicate webhooks (same message sent twice)
//   - Rapid lead replies during active processing (main path is already running)
// IMPORTANT: This now also blocks the main path, not just quick reply.
const lastReply = staticData[dedupKey] || 0;
const isDuplicate = (now - lastReply) <= 10000; // Within 10 seconds = duplicate
if (!isDuplicate) {
  staticData[dedupKey] = now;
}

// --- LEAD ID CACHE ---
let leadId = $json.lead_id || '';
if (!leadId && phone) {
  leadId = staticData[leadCacheKey] || '';
}

// --- SESSION DATA FOR WRAP-UP ---
const waSessionSummary = session.summary || '';

return {
  json: {
    ...$json,
    lead_id: leadId,
    // FIX: wa_is_new_session now also checks !isDuplicate
    // This prevents a second message (within 30s) from entering the main path
    // even if staticData has a race condition on isNewSession
    wa_is_new_session: shouldRunPathB && !isDuplicate,
    wa_session_active: !isNewSession,
    wa_should_quick_reply: !isDuplicate,        // Block quick reply for duplicates too
    wa_session_summary: waSessionSummary,
    wa_pathb_running: pathBRunning || isDuplicate // Block main path if dedup triggered
  }
};

const rawOutput = $json.output || '';
const phone = ($('Normalize Input').first().json.incoming_phone || '').replace(/\D/g, '');
const staticData = $getWorkflowStaticData('global');
const sessionKey = `wa_session_${phone}`;
const leadCacheKey = `wa_lead_${phone}`;

// Get lead_id — try Normalize Input first, then staticData cache
const leadId = $('Normalize Input').first().json.lead_id
  || (phone ? (staticData[leadCacheKey] || $('WA Context Builder').first().json.content[0].text.data[0].id || '') : '');

// Extract [NEEDS_FAQ: question] if present
const needsFaqMatch = rawOutput.match(/\[NEEDS_FAQ:\s*(.+?)\]/i);
const needsFaqQuestion = needsFaqMatch ? needsFaqMatch[1].trim() : '';

// Clean message — strip any internal markers
const replyText = rawOutput
  .replace(/\[SESSION_COMPLETE\]/g, '')
  .replace(/^---$/gm, '')
  .trim();

// Rolling timer: wrap-up fires 90 minutes after the LAST message
const wrapUp = new Date(Date.now() + 90 * 60 * 1000); // now + 90 min
// Zoho CRM requires datetime without milliseconds: yyyy-MM-ddTHH:mm:ss+00:00
const wrapUpTime = wrapUp.toISOString().split('.')[0] + '+00:00';

// Update session rolling timestamp
if (staticData[sessionKey]) {
  staticData[sessionKey].lastReplyAt = Date.now();
  staticData[sessionKey].wrapUpTime = wrapUpTime;
}

return {
  json: {
    ...$json,
    lead_id: leadId,
    reply_text: replyText,
    wrap_up_time: wrapUpTime,   // Zoho-compatible datetime for Action_Date
    needs_faq_question: needsFaqQuestion
  }
};

