// ✅ Fix: read CRM data from Get Lead info, not $json (which is Get FAQs output)
const crmData = (() => {
  try {
    const mcpOut = $("Get Lead info").first().json;
    const content = mcpOut?.content?.[0]?.text;
    const parsed =
      typeof content === "object" ? content : JSON.parse(content || "{}");
    return (Array.isArray(parsed?.data) ? parsed.data[0] : parsed) || {};
  } catch (e) {
    return {};
  }
})();

const normalize = (() => {
  try {
    return $("Normalize Input").first().json;
  } catch (e) {
    return {};
  }
})();

// ✅ Fix: wa_session_summary from WA Session Gate (reads staticData on every run)
const sessionGate = (() => {
  try {
    return $("WA Session Gate").first().json;
  } catch (e) {
    return {};
  }
})();

// ✅ New-lead fallback: a brand-new lead is created mid-run at "Quick Create Lead",
// so its id is NOT in Get Lead info (ran before creation) nor in WA Session Gate
// (also ran before creation — it only caches the id for the NEXT message).
// The fresh id lives on "Capture Lead ID". This node only runs on the unknown-lead
// (true) branch, so guard with try/catch — it throws on the existing-lead branch.
const capturedLeadId = (() => {
  try {
    return $("Capture Lead ID").first().json.lead_id || "";
  } catch (e) {
    return "";
  }
})();

// Build country context — $input comes from Country Context WA data table (ALL rows, no filter)
const leadCountry = (crmData.Primary_Country || crmData.Country || "").trim();
let countryContext = "";
try {
  const ctxItems = $input.all().map((i) => i.json);

  if (leadCountry && ctxItems.length > 0) {
    // Known country → find matching row
    const match = ctxItems.find(
      (r) => (r.country || "").toLowerCase() === leadCountry.toLowerCase()
    );
    if (match) {
      countryContext = [
        '=== COUNTRY CONTEXT ===',
        `Country: ${match.country}`,
        `Cluster: ${match.cluster || 'unknown'}`,
        `Registration Model: ${match.registration_model || 'unknown'}`,
        `Registration Description: ${match.registration_description || ''}`,
        `Distribution Model: ${match.distribution_model || ''}`,
