        `Qualification Questions (Distribution): ${match.questions_distribution || '[]'}`,
        `Qualification Questions (Market): ${match.questions_market || '[]'}`,
        `Qualification Questions (Portfolio): ${match.questions_portfolio || '[]'}`,
        `Qualification Questions (Registration): ${match.questions_registration || '[]'}`,
        '=== END COUNTRY CONTEXT ==='
      ].join('\n');
    } else {
      // Known country but NOT in our table → list available countries
      const available = ctxItems
        .filter((r) => r.country)
        .map((r) => r.country);
      countryContext = [
        '=== COUNTRY CONTEXT ===',
        `Lead Country: ${leadCountry}`,
        `Status: COUNTRY NOT IN OUR ACTIVE MARKETS`,
        `Available Markets: ${available.join(', ')}`,
        'Note: This country is not in our current registration/out-licensing portfolio.',
        '=== END COUNTRY CONTEXT ==='
      ].join('\n');
    }
  } else if (ctxItems.length > 0) {
    // Unknown country → send ALL country summaries so AI can decide
    const countrySummaries = ctxItems
      .filter((r) => r.country)
      .map((r) => `  - ${r.country} (${r.cluster || 'unknown'}, ${r.registration_model || 'unknown'})`)
      .join('\n');
    const available = ctxItems
      .filter((r) => r.country)
      .map((r) => r.country);
    countryContext = [
      '=== COUNTRY CONTEXT ===',
      'Lead Country: UNKNOWN — must ask the lead',
      `Available Markets: ${available.join(', ')}`,
      '',
      'Country Summaries:',
      countrySummaries,
      '',
      'Instructions: Ask the lead which country they operate in. Once known, update CRM via ZohoCRM_updateRecords with { "Primary_Country": "[country]" } (field is Primary_Country, NOT Country). Then use the matching context above for your pitch.',
      '=== END COUNTRY CONTEXT ==='
    ].join('\n');
  }
} catch (e) {}

return {
