// ============================================================
// CALCULATE BUSINESS DATES
// Placed: between Check WA Session and AI Agent
//
// Adds to context:
//   next_business_day_t2      — T+2 business days
//   next_business_day_t2_day  — day name (e.g. "Wednesday")
//   next_business_day_t5      — T+5 business days
//   next_business_day_t5_day  — day name
//   bumped_past_holiday       — name of holiday skipped (if any)
//   upcoming_holidays         — holidays in the next 30 days (name + date)
//
// AI Agent reads these directly — no date math needed by AI.
// All existing JSON fields pass through unchanged.
// ============================================================

const item = $input.item.json;
const country = item.country || "Venezuela";

// Country name → ISO code for Nager.Date API
const COUNTRY_CODES = {
  Venezuela: "VE",
  Panama: "PA",
  Guatemala: "GT",
  Honduras: "HN",
  "Costa Rica": "CR",
  "El Salvador": "SV",
  Nicaragua: "NI",
  "Dominican Republic": "DO",
  Colombia: "CO",
  Ecuador: "EC",
  Mexico: "MX",
  Peru: "PE",
  Bolivia: "BO",
  Paraguay: "PY",
  Uruguay: "UY",
  Argentina: "AR",
  Chile: "CL",
  Brazil: "BR",
};
const countryCode = COUNTRY_CODES[country] || "VE";

// Country → UTC offset string for Action_Date (10 AM local time)
const TIMEZONE_OFFSETS = {
  VE: "-04:00",  // Venezuela Time (VET)
  PA: "-05:00",  // Panama (EST, no DST)
  GT: "-06:00",  // Guatemala (CST)
  HN: "-06:00",  // Honduras
  SV: "-06:00",  // El Salvador
  NI: "-06:00",  // Nicaragua
  CR: "-06:00",  // Costa Rica
  DO: "-04:00",  // Dominican Republic (AST)
  CO: "-05:00",  // Colombia (COT)
  EC: "-05:00",  // Ecuador (ECT)
  MX: "-06:00",  // Mexico (CST, majority)
  PE: "-05:00",  // Peru (PET)
  BO: "-04:00",  // Bolivia (BOT)
  PY: "-04:00",  // Paraguay (PYT)
  UY: "-03:00",  // Uruguay (UYT)
  AR: "-03:00",  // Argentina (ART, no DST)
  CL: "-04:00",  // Chile (CLT)
  BR: "-03:00",  // Brazil (BRT, Brasilia)
};
const tzOffset = TIMEZONE_OFFSETS[countryCode] || "-04:00";
const localTime = `T10:00:00${tzOffset}`;

const year = new Date().getFullYear();

// Fetch public holidays — fail silently if unavailable
// holidayMap: { 'YYYY-MM-DD': 'Holiday Name' }
let holidayMap = {};
try {
  const [r1, r2] = await Promise.all([
    fetch(`https://date.nager.at/api/v3/PublicHolidays/${year}/${countryCode}`),
    fetch(
      `https://date.nager.at/api/v3/PublicHolidays/${year + 1}/${countryCode}`,
    ),
  ]);
  const [h1, h2] = await Promise.all([
    r1.ok ? r1.json() : [],
    r2.ok ? r2.json() : [],
  ]);
  [...h1, ...h2].forEach((h) => {
    holidayMap[h.date] = h.localName || h.name;
  });
} catch (e) {
  // API unavailable — weekend-only check applies
}

const holidaySet = new Set(Object.keys(holidayMap));
const DAYS = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
];

// Advance a date past weekends and holidays, tracking skipped holidays
function nextBusinessDay(d, steps) {
  let date = new Date(d);
  let added = 0;
  let skippedHolidays = [];

  while (added < steps) {
    date.setDate(date.getDate() + 1);
    const dow = date.getDay();
    const ds = date.toISOString().split("T")[0];

    const isWeekend = dow === 0 || dow === 6;
    const isHoliday = holidaySet.has(ds);

    if (isHoliday && !isWeekend) {
      skippedHolidays.push(`${ds} (${holidayMap[ds]})`);
    }

    if (!isWeekend && !isHoliday) {
      added++;
    }
  }
  return { date: date.toISOString().split("T")[0], skipped: skippedHolidays };
}

// Find upcoming holidays in the next 30 days
function upcomingHolidays(fromDate, days) {
  const results = [];
  const start = new Date(fromDate);
  for (let i = 1; i <= days; i++) {
    const d = new Date(start);
    d.setDate(start.getDate() + i);
    const ds = d.toISOString().split("T")[0];
    if (holidaySet.has(ds)) {
      results.push(`${ds} ${DAYS[d.getDay()]}: ${holidayMap[ds]}`);
    }
  }
  return results;
}

const today = new Date();
const r2 = nextBusinessDay(today, 2);
const r5 = nextBusinessDay(today, 5);

const allSkipped = [...new Set([...r2.skipped, ...r5.skipped])];
const upcoming = upcomingHolidays(today, 30);

return {
  json: {
    ...item,
    next_business_day_t2: r2.date + localTime,
    next_business_day_t2_day: DAYS[new Date(r2.date).getDay()],
    next_business_day_t5: r5.date + localTime,
    next_business_day_t5_day: DAYS[new Date(r5.date).getDay()],
    bumped_past_holiday: allSkipped.length > 0 ? allSkipped.join(", ") : "none",
    upcoming_holidays:
      upcoming.length > 0 ? upcoming.join(" | ") : "none in next 30 days",
  },
};

