// Lead data from bump_to_business_day (first input)
const lead = $('bump_to_business_day').first().json;

// Country context from Data Table (second input)
const ctxItems = $('Country Context').all();
const ctx = ctxItems.length > 0 ? ctxItems[0].json : {};

// Build one text block the AI can read
const countryContextBlock = [
  '=== COUNTRY CONTEXT ===',
  `Cluster: ${ctx.cluster || 'unknown'}`,
  `Registration Model: ${ctx.registration_model || 'unknown'}`,
  `Registration Description: ${ctx.registration_description || ''}`,
  `Distribution Model: ${ctx.distribution_model || ''}`,
  `Market Status: ${ctx.market_status || 'unknown'}`,
  `Excluded Topics: ${ctx.excluded_topics || ''}`,
  '',
  `Qualification Questions (Company): ${ctx.questions_company || '[]'}`,
  `Qualification Questions (Distribution): ${ctx.questions_distribution || '[]'}`,
  `Qualification Questions (Market): ${ctx.questions_market || '[]'}`,
  `Qualification Questions (Portfolio): ${ctx.questions_portfolio || '[]'}`,
  `Qualification Questions (Registration): ${ctx.questions_registration || '[]'}`,
  '=== END COUNTRY CONTEXT ==='
].join('\n');

return [{
  json: {
    ...lead,
    country_context: countryContextBlock
  }
}];

